mapper.select:
SELECT s.origin_id AS note_id, s.source_id, v.version, n.title, v.body_markdown, v.status AS index_status, v.created_at AS updated_at, s.status AS source_status FROM ma_source s JOIN ma_source_version v ON v.source_id = s.source_id AND v.version = s.current_version JOIN ma_note_version n ON n.source_id = v.source_id AND n.version = v.version WHERE s.account_id = #{accountId} AND s.type = 'NOTE' AND s.status = 'ACTIVE'
AND (v.created_at, s.origin_id) < (#{beforeTime}, #{beforeId})
ORDER BY v.created_at DESC, s.origin_id DESC LIMIT #{limit}

SELECT s.source_id,s.type,s.origin_id,s.status,s.created_at,s.current_version, v.status AS index_status,v.answer_state FROM ma_source s JOIN ma_source_version v ON v.source_id = s.source_id AND v.version = s.current_version WHERE s.account_id = #{accountId} AND s.status = 'ACTIVE' AND s.type = #{type}
AND (s.created_at, s.source_id) < (#{beforeTime}, #{beforeId})
ORDER BY s.created_at DESC,s.source_id DESC LIMIT #{limit}
